INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901912, 7, 1, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, weenie_Class_Id, stack_Size) VALUES (@e, 0, 12, 0, 1, NULL, NULL, NULL), (@e, 1, 10, 0, 1, 'Judge Fang taught that a serpent is never the same creature twice. It sheds what it was, and is renewed.', NULL, NULL), (@e, 2, 10, 0, 1, 'Bring me a weapon of legend, one of the rare blades or bows the old masters made, together with the shed skin of a Sclavus. I will renew it in the Judge''s manner, as a weapon of the Serpent of the same kind.', NULL, NULL), (@e, 3, 10, 0, 1, 'And if you carry the Judge''s own bow, Serpent''s Flight, bring three skins. It has waited a long time to ascend.', NULL, NULL);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901912, 1, 1, 901911, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, weenie_Class_Id, stack_Size) VALUES (@e, 0, 12, 0, 1, NULL, NULL, NULL), (@e, 1, 10, 0, 1, 'A shed skin, and a fine one. Keep it in your pack and hand me the weapon you wish renewed.', NULL, NULL);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901912, 1, 1, 30340, NULL);
